<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    :root {
      --primary: #3861FB;
      --primary-hover: #2a4ed4;
      --text-primary: #0D1421;
      --text-secondary: #808A9D;
      --text-muted: #A0AEC0;
      --bg-body: #F8FAFC;
      --bg-surface: #FFFFFF;
      --bg-hover: #F1F5F9;
      --border: #E2E8F0;
      --border-light: #F1F5F9;
      --green: #16c784;
      --green-bg: rgba(22, 199, 132, 0.08);
      --red: #ea3943;
      --red-bg: rgba(234, 57, 67, 0.08);
      --shadow-sm: 0 1px 2px rgba(13, 20, 33, 0.04);
      --shadow-md: 0 4px 12px rgba(13, 20, 33, 0.06);
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 14px;
    }

    * { margin: 0; padding: 0; box-sizing: border-box; }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg-body);
      color: var(--text-primary);
      font-size: 14px;
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
    }

    /* Utility */
    .mono { font-family: 'JetBrains Mono', monospace; }
    .text-green { color: var(--green); }
    .text-red { color: var(--red); }
    .text-secondary { color: var(--text-secondary); }
