    const promoText = document.getElementById('promoText');
    const promoTag = document.querySelector('.promo-tag');

    function showPromo(i) {
      promoIdx = (i + promoMessages.length) % promoMessages.length;
      promoText.textContent = promoMessages[promoIdx].text;
      promoTag.textContent = promoMessages[promoIdx].tag;
    }
    document.getElementById('promoPrev').addEventListener('click', () => showPromo(promoIdx - 1));
    document.getElementById('promoNext').addEventListener('click', () => showPromo(promoIdx + 1));
    setInterval(() => showPromo(promoIdx + 1), 6000);

    // ========================
    // READ MORE ACCORDION
    // ========================
    const readMoreBtn = document.getElementById('readMoreBtn');
    const summaryExtra = document.getElementById('summaryExtra');
    readMoreBtn.addEventListener('click', () => {
      const open = summaryExtra.classList.toggle('open');
      readMoreBtn.setAttribute('aria-expanded', open);
      readMoreBtn.querySelector('svg').style.transform = open ? 'rotate(180deg)' : '';
    });

    // ========================
    // INITIAL RENDER
    // ========================
    renderTable();
  </script>
</body>
</html>
